def linear_search(items, target):
    for i in range(len(items)):
        if items[i] == target:
            return i    # position found
    return -1           # not in the list

print(linear_search(["Karachi", "Lahore", "Islamabad", "Faisalabad"], "Islamabad"))    # 2

cities = ["Karachi", "Lahore", "Islamabad", "Faisalabad"]
target = "Islamabad"

def linear_search():
    for i in range(len(cities)):
        print("Check position", i, ":", cities[i])
        if cities[i] == target:
            return i
    return -1

position = linear_search()
if position == -1:
    print(target, "is not in the list;", len(cities), "comparisons done.")
else:
    print(target, "found at position", position, "after", position + 1, "comparisons.")
